class DanTextShimmer{static instances=[];constructor(element){Object.assign(this,{element,duration:parseFloat(element.getAttribute('data-duration')),ease:element.getAttribute('data-ease'),stagger:parseFloat(element.getAttribute('data-stagger')),shimmerSize:getComputedStyle(element).getPropertyValue('--shimmer-size'),animation:null});this.initialize()}
initialize(){this.element.parentElement.removeAttribute("data-flickering");this.createAnimation()}
createAnimation(){const animate=()=>{gsap.set(this.element,{backgroundPosition:"-100% top"});this.animation=gsap.to(this.element,{backgroundPosition:`calc(100% + ${this.shimmerSize}) top`,duration:this.duration,ease:this.ease,onComplete:()=>{gsap.delayedCall(this.stagger,animate)}})};animate()}
destroy(){if(this.animation){this.animation.kill()}}
static destroyAll(){DanTextShimmer.instances.forEach((instance)=>instance.destroy());DanTextShimmer.instances=[]}}
const dancepad_text_shimmer=()=>{DanTextShimmer.destroyAll();const instances=[];const animations={};document.querySelectorAll(".dan-text-shimmer__inner").forEach((element,index)=>{const instance=new DanTextShimmer(element);instances.push(instance);animations[`anim${index}`]=instance.animation});DanTextShimmer.instances=instances;return animations}